//! States mode: the 50 states and DC as pies (the cluster donuts' pipeline)
//! over their outlines, and the panel's states chart. The counts are the
//! 2020 P.L. 94-171 P2 state rows (`states_data.rs`, generated by
//! `scripts/gen-race-states.py`), the outlines the Census Bureau's 1:20M
//! cartographic boundary states (`states.geojson`, same script).
//!
//! Hidden groups (the legend's toggles) are taken out and the shares
//! RENORMALISED over the groups still shown -- as the cluster donuts do --
//! so a pie is always a whole circle and a bar always 100% wide, and
//! hiding White answers "of everyone else, who lives here". A pie's SIZE
//! still counts everyone, as a donut's does.

use std::sync::OnceLock;

use gpui_maps::census::breakdowns::MercatorBounds;
use gpui_maps::render::donut::Donut;

use super::states_data::STATE_ROWS;
use super::walker;

/// The state pies' donut layer.
pub const PIE_LAYER: &str = "race-states";
/// The state outlines' overlay source.
pub const OUTLINE_SOURCE: &str = "race-state-outlines";
/// The pies' total labels (a point source, one per pie).
pub const LABEL_SOURCE: &str = "race-state-labels";

/// One state's P2 row: the 8 groups in [`walker::GROUPS`] order, the pie's
/// anchor (inside the state: its largest polygon's pole of
/// inaccessibility) and its box `[west, south, east, north]` (Alaska's
/// without the Aleutians west of the antimeridian).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct StateRow {
    pub fips: u8,
    pub abbr: &'static str,
    pub name: &'static str,
    pub counts: [u32; 8],
    pub anchor: (f64, f64),
    pub bbox: [f64; 4],
}

impl StateRow {
    pub fn total(&self) -> u64 {
        self.counts.iter().map(|&c| u64::from(c)).sum()
    }
}

/// Every row, by FIPS code.
pub fn rows() -> &'static [StateRow] {
    &STATE_ROWS
}

/// The US's groups: every state's, summed.
pub fn us_counts() -> [u64; 8] {
    let mut out = [0u64; 8];
    for r in rows() {
        for (o, &c) in out.iter_mut().zip(&r.counts) {
            *o += u64::from(c);
        }
    }
    out
}

/// `counts` as percentages of the groups `mask` shows (bit `g` set: group
/// `g` shown), renormalised so the shown ones sum to 100; a hidden group is
/// 0. Nothing shown, or no one: all 0.
pub fn shares(counts: &[u64; 8], mask: u8) -> [f32; 8] {
    let shown = |g: usize| mask & (1 << g) != 0;
    let total: u64 = (0..8).filter(|&g| shown(g)).map(|g| counts[g]).sum();
    if total == 0 {
        return [0.0; 8];
    }
    std::array::from_fn(|g| if shown(g) { (counts[g] as f64 * 100.0 / total as f64) as f32 } else { 0.0 })
}

/// A state's counts widened.
pub fn counts64(row: &StateRow) -> [u64; 8] {
    row.counts.map(u64::from)
}

/// How the states chart is ordered.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortKey {
    /// A to Z.
    Name,
    /// Largest first.
    Population,
    /// Group `g`'s (renormalised) share, largest first.
    Share(usize),
}

/// The row indices (into [`rows`]) in `key`'s order. Ties go A to Z, so
/// the order is total and stable from frame to frame.
pub fn sorted(key: SortKey, mask: u8) -> Vec<usize> {
    let rows = rows();
    let mut idx: Vec<usize> = (0..rows.len()).collect();
    match key {
        SortKey::Name => idx.sort_by(|&a, &b| rows[a].name.cmp(rows[b].name)),
        SortKey::Population => idx.sort_by(|&a, &b| rows[b].total().cmp(&rows[a].total()).then(rows[a].name.cmp(rows[b].name))),
        SortKey::Share(g) => {
            let share = |i: usize| shares(&counts64(&rows[i]), mask)[g];
            idx.sort_by(|&a, &b| share(b).total_cmp(&share(a)).then(rows[a].name.cmp(rows[b].name)));
        }
    }
    idx
}

/// The pies' radii (logical px): area by population -- the radius goes as
/// the square root -- with California, the largest, at [`PIE_MAX_R`], and
/// never under [`PIE_MIN_R`], so Rhode Island, Delaware and DC stay
/// readable at the whole-US view. Scaled with the zoom by [`zoom_scale`].
pub const PIE_MAX_R: f32 = 38.0;
pub const PIE_MIN_R: f32 = 9.0;

/// The pies grow by sqrt(2) per zoom level from z4, between 0.8x and 2.5x:
/// they keep to their states at the US view and grow as a state fills the
/// screen, without covering it.
pub fn zoom_scale(zoom: f64) -> f32 {
    2f32.powf(((zoom - 4.0) * 0.5) as f32).clamp(0.8, 2.5)
}

/// Zoom scale to 1/20: the pies are re-sent only when this changes.
pub fn quantised_scale(zoom: f64) -> f32 {
    (zoom_scale(zoom) * 20.0).round() / 20.0
}

fn max_total() -> u64 {
    rows().iter().map(StateRow::total).max().unwrap_or(1).max(1)
}

/// A state of `pop` people's pie radius at scale 1.
pub fn pie_radius(pop: u64) -> f32 {
    let r = PIE_MAX_R * (pop as f64 / max_total() as f64).sqrt() as f32;
    r.max(PIE_MIN_R)
}

/// The pies the map is given and the row behind each (the same order:
/// `donut_at`'s index is an index into `order`): largest first, so a small
/// state's pie draws -- and is hit -- over a big neighbour's (DC over
/// Maryland). Hidden groups out of the rings; with a state selected the
/// others are faded.
pub struct Pies {
    pub donuts: Vec<Donut>,
    pub order: Vec<usize>,
}

/// The selected state's pie is never smaller than this (logical px): framed
/// on its own, Rhode Island's floored pie would be a speck.
pub const SELECTED_MIN_R: f32 = 34.0;

/// The pies' alpha while another state is selected.
pub const FADED: f32 = 0.55;

pub fn pies(mask: u8, scale: f32, selected: Option<usize>) -> Pies {
    let rows = rows();
    let mut order: Vec<usize> = (0..rows.len()).filter(|&i| (0..8).any(|g| mask & (1 << g) != 0 && rows[i].counts[g] > 0)).collect();
    order.sort_by(|&a, &b| rows[b].total().cmp(&rows[a].total()).then(a.cmp(&b)));
    let donuts = order
        .iter()
        .map(|&i| {
            let r = &rows[i];
            let counts = std::array::from_fn(|g| if mask & (1 << g) != 0 { r.counts[g] } else { 0 });
            let alpha = if selected.is_none_or(|s| s == i) { 1.0 } else { FADED };
            let mut radius_px = pie_radius(r.total()) * scale;
            if selected == Some(i) {
                radius_px = radius_px.max(SELECTED_MIN_R);
            }
            Donut { lon: r.anchor.0, lat: r.anchor.1, radius_px, counts, alpha }
        })
        .collect();
    Pies { donuts, order }
}

/// The pies' total labels, as the cluster donuts' count labels are drawn
/// (`clusters::labels_geojson`): each state's population in Walker's
/// format ("5.1M"), 12 px `#263443`, centred in its pie, never dropped
/// for collision -- one per pie in `pies`, at the pie's own alpha (a
/// faded pie's label fades with it). Like a donut's, the label counts
/// EVERYONE in the state while the ring shows only the groups the legend
/// keeps, so hiding a group never blanks or shrinks it; a state with
/// every group hidden has no pie and so no label.
pub fn labels_geojson(pies: &Pies) -> String {
    let rows = rows();
    let features: Vec<serde_json::Value> = pies
        .order
        .iter()
        .zip(&pies.donuts)
        .map(|(&i, d)| {
            let total = u32::try_from(rows[i].total()).unwrap_or(u32::MAX);
            serde_json::json!({
                "type": "Feature",
                "geometry": {"type": "Point", "coordinates": [d.lon, d.lat]},
                "properties": {
                    "fips": rows[i].fips,
                    "circle-radius": 0,
                    "text-field": walker::count_label(total),
                    "text-size": walker::COUNT_LABEL_SIZE,
                    "text-color": super::clusters::label_color(d.alpha),
                    "text-allow-overlap": true,
                },
            })
        })
        .collect();
    serde_json::json!({"type": "FeatureCollection", "features": features}).to_string()
}

/// The outlines as committed: one MultiLineString per state, `fips` its
/// only property.
pub const OUTLINES: &str = include_str!("states.geojson");

/// The outlines' line colour and width, and the selected state's.
pub const OUTLINE_COLOR: &str = "#5b6675";
pub const OUTLINE_WIDTH: f64 = 0.8;
pub const SELECTED_COLOR: &str = "#111827";
pub const SELECTED_WIDTH: f64 = 2.2;

/// The outlines with their paint, the selected state (`fips`) drawn darker
/// and wider, and last so it draws over its neighbours' shared borders.
pub fn outlines_geojson(selected_fips: Option<u8>) -> String {
    static PARSED: OnceLock<serde_json::Value> = OnceLock::new();
    let parsed = PARSED.get_or_init(|| serde_json::from_str(OUTLINES).expect("states.geojson parses"));
    let mut features: Vec<serde_json::Value> = parsed["features"].as_array().cloned().unwrap_or_default();
    for f in &mut features {
        let on = f["properties"]["fips"].as_u64().map(|n| n as u8) == selected_fips && selected_fips.is_some();
        let props = f["properties"].as_object_mut().expect("properties");
        props.insert("line-color".into(), (if on { SELECTED_COLOR } else { OUTLINE_COLOR }).into());
        props.insert("line-width".into(), (if on { SELECTED_WIDTH } else { OUTLINE_WIDTH }).into());
    }
    features.sort_by_key(|f| f["properties"]["fips"].as_u64().map(|n| n as u8) == selected_fips);
    serde_json::json!({"type": "FeatureCollection", "features": features}).to_string()
}

/// The furthest a state fit zooms in (DC's box would want z11).
pub const FIT_MAX_ZOOM: f64 = 9.0;
/// Room left round a fitted state, logical px.
pub const FIT_PAD: f64 = 48.0;

/// The camera that frames row `i` in a `w` x `h` view: `(lon, lat, zoom)`.
pub fn fit(i: usize, w: f64, h: f64) -> (f64, f64, f64) {
    let [west, south, east, north] = rows()[i].bbox;
    let x = |lon: f64| (lon + 180.0) / 360.0;
    let y = |lat: f64| {
        let s = lat.to_radians().sin();
        0.5 - ((1.0 + s) / (1.0 - s)).ln() / (4.0 * std::f64::consts::PI)
    };
    let b = MercatorBounds { x0: x(west), y0: y(north), x1: x(east), y1: y(south) };
    let (lon, lat, zoom) = b.fit(w, h, FIT_PAD, FIT_MAX_ZOOM);
    (lon, lat, zoom.max(walker::MIN_ZOOM))
}

/// The row with FIPS code `fips`.
pub fn by_fips(fips: u8) -> Option<usize> {
    rows().iter().position(|r| r.fips == fips)
}

#[cfg(test)]
mod tests {
    use super::*;

    const ALL: u8 = 0xFF;

    #[test]
    fn fifty_one_rows_sum_to_the_us_total_and_walkers_groups() {
        assert_eq!(rows().len(), 51, "the 50 states and DC: the dots' coverage (no Puerto Rico)");
        assert_eq!(rows().iter().map(StateRow::total).sum::<u64>(), walker::US_TOTAL);
        let us = us_counts();
        for (g, group) in walker::GROUPS.iter().enumerate() {
            assert_eq!(us[g], group.people, "{}", group.label);
        }
        let mut fips: Vec<u8> = rows().iter().map(|r| r.fips).collect();
        fips.dedup();
        assert_eq!(fips.len(), 51, "one row per state, by FIPS");
        assert_eq!(rows()[by_fips(6).unwrap()].name, "California");
        assert_eq!(rows()[by_fips(11).unwrap()].abbr, "DC");
    }

    #[test]
    fn every_anchor_sits_inside_its_box() {
        for r in rows() {
            let [w, s, e, n] = r.bbox;
            assert!(w < e && s < n, "{}", r.abbr);
            assert!((w..=e).contains(&r.anchor.0) && (s..=n).contains(&r.anchor.1), "{} anchor {:?} outside {:?}", r.abbr, r.anchor, r.bbox);
        }
    }

    #[test]
    fn shares_renormalise_over_the_shown_groups() {
        let c = [10, 30, 60, 0, 0, 0, 0, 0];
        let s = shares(&c, ALL);
        assert!((s[0] - 10.0).abs() < 1e-4 && (s[2] - 60.0).abs() < 1e-4);
        // Hide group 2: the rest renormalise to 100.
        let s = shares(&c, ALL & !(1 << 2));
        assert_eq!(s[2], 0.0);
        assert!((s[0] - 25.0).abs() < 1e-4 && (s[1] - 75.0).abs() < 1e-4);
        assert!((s.iter().sum::<f32>() - 100.0).abs() < 1e-3);
        assert_eq!(shares(&c, 0), [0.0; 8]);
        assert_eq!(shares(&[0; 8], ALL), [0.0; 8]);
    }

    #[test]
    fn sorting_by_name_population_and_share() {
        let by_name = sorted(SortKey::Name, ALL);
        assert_eq!(rows()[by_name[0]].name, "Alabama");
        assert_eq!(rows()[by_name[50]].name, "Wyoming");
        let by_pop = sorted(SortKey::Population, ALL);
        assert_eq!(rows()[by_pop[0]].abbr, "CA");
        assert_eq!(rows()[by_pop[1]].abbr, "TX");
        assert_eq!(rows()[by_pop[50]].abbr, "WY");
        // Hispanic share: New Mexico leads; White share: Vermont or Maine.
        let by_hisp = sorted(SortKey::Share(0), ALL);
        assert_eq!(rows()[by_hisp[0]].abbr, "NM");
        let by_white = sorted(SortKey::Share(1), ALL);
        assert!(["VT", "ME", "WV"].contains(&rows()[by_white[0]].abbr), "{}", rows()[by_white[0]].abbr);
        // Every key is a permutation.
        for key in [SortKey::Name, SortKey::Population, SortKey::Share(4)] {
            let mut v = sorted(key, ALL);
            v.sort_unstable();
            assert_eq!(v, (0..51).collect::<Vec<_>>());
        }
    }

    #[test]
    fn a_share_sort_follows_the_renormalised_shares() {
        // Hiding White moves the share of Black up everywhere, but a
        // share sort reads the renormalised figure, as the bars show it.
        let mask = ALL & !(1 << 1);
        let order = sorted(SortKey::Share(2), mask);
        let s = |i: usize| shares(&counts64(&rows()[i]), mask)[2];
        assert!(order.windows(2).all(|w| s(w[0]) >= s(w[1])));
        // A hidden group's share is 0 everywhere: the order falls back to A-Z.
        assert_eq!(sorted(SortKey::Share(1), mask), sorted(SortKey::Name, mask));
    }

    #[test]
    fn pie_area_goes_with_population_capped_and_floored() {
        let ca = rows()[by_fips(6).unwrap()].total();
        assert_eq!(pie_radius(ca), PIE_MAX_R);
        assert!((pie_radius(ca / 4) - PIE_MAX_R / 2.0).abs() < 1e-3, "a quarter the people, half the radius (a quarter the area)");
        assert_eq!(pie_radius(1), PIE_MIN_R);
        let dc = rows()[by_fips(11).unwrap()].total();
        assert_eq!(pie_radius(dc), PIE_MIN_R, "DC is floored, readable");
        assert!(zoom_scale(3.0) >= 0.8 && zoom_scale(4.0) == 1.0 && zoom_scale(20.0) == 2.5);
    }

    #[test]
    fn pies_draw_largest_first_so_small_states_sit_on_top() {
        let p = pies(ALL, 1.0, None);
        assert_eq!(p.donuts.len(), 51);
        assert_eq!(p.order.len(), 51);
        assert_eq!(rows()[p.order[0]].abbr, "CA");
        assert!(p.donuts.windows(2).all(|w| w[0].radius_px >= w[1].radius_px));
        let dc = p.order.iter().position(|&i| rows()[i].abbr == "DC").unwrap();
        let md = p.order.iter().position(|&i| rows()[i].abbr == "MD").unwrap();
        assert!(dc > md, "DC draws after (over) Maryland");
        assert!(p.donuts.iter().all(|d| d.alpha == 1.0));
    }

    #[test]
    fn pies_drop_hidden_groups_and_fade_the_unselected() {
        let mask = 0b0000_0010; // White only
        let sel = by_fips(6).unwrap();
        let p = pies(mask, 1.0, Some(sel));
        assert!(p.donuts.iter().all(|d| d.counts.iter().enumerate().all(|(g, &c)| g == 1 || c == 0)));
        for (d, &i) in p.donuts.iter().zip(&p.order) {
            assert_eq!(d.alpha, if i == sel { 1.0 } else { FADED });
            // Size still counts everyone (and the selected pie is at least
            // SELECTED_MIN_R).
            let r = pie_radius(rows()[i].total());
            assert_eq!(d.radius_px, if i == sel { r.max(SELECTED_MIN_R) } else { r });
        }
        assert!(pies(0, 1.0, None).donuts.is_empty(), "nothing shown, nothing drawn");
        let ri = by_fips(44).unwrap();
        let p = pies(ALL, 1.0, Some(ri));
        let k = p.order.iter().position(|&i| i == ri).unwrap();
        assert_eq!(p.donuts[k].radius_px, SELECTED_MIN_R, "a selected small state's pie is readable");
    }

    /// The defect: a state's pie had no total in its white centre
    /// while every cluster donut has its count. Every pie gets one, in the
    /// clusters' format, at the pie's place and alpha; hiding groups keeps
    /// the total (everyone), and only a pie that is gone loses its label.
    #[test]
    fn every_pie_carries_its_states_total_like_a_cluster_count() {
        let labels = |mask: u8, sel: Option<usize>| -> Vec<serde_json::Value> {
            let v: serde_json::Value = serde_json::from_str(&labels_geojson(&pies(mask, 1.0, sel))).unwrap();
            v["features"].as_array().unwrap().clone()
        };
        let all = labels(ALL, None);
        assert_eq!(all.len(), 51, "one total per pie");
        let sc = by_fips(45).unwrap();
        let f = all.iter().find(|f| f["properties"]["fips"] == 45).expect("South Carolina's label");
        assert_eq!(f["properties"]["text-field"], walker::count_label(rows()[sc].total() as u32));
        assert_eq!(f["properties"]["text-field"], "5.1M");
        assert_eq!(f["properties"]["text-size"], f64::from(walker::COUNT_LABEL_SIZE));
        assert_eq!(f["properties"]["text-color"], "#263443ff");
        assert_eq!(f["geometry"]["coordinates"][0], rows()[sc].anchor.0);
        let ca = all.iter().find(|f| f["properties"]["fips"] == 6).unwrap();
        assert_eq!(ca["properties"]["text-field"], "40M", "39,538,223 in Walker's whole-millions format");
        // Hiding White: the same totals, not blanks and not the rest's.
        let no_white = labels(ALL & !(1 << 1), None);
        assert_eq!(no_white.len(), 51);
        for f in &no_white {
            let same = all.iter().find(|a| a["properties"]["fips"] == f["properties"]["fips"]).unwrap();
            assert_eq!(f["properties"]["text-field"], same["properties"]["text-field"]);
        }
        // A selection fades the others' labels with their pies.
        let sel = labels(ALL, Some(sc));
        assert_eq!(sel.len(), 51);
        for f in &sel {
            let want = if f["properties"]["fips"] == 45 { "#263443ff".to_string() } else { super::super::clusters::label_color(FADED) };
            assert_eq!(f["properties"]["text-color"], want.as_str());
        }
        assert!(labels(0, None).is_empty(), "no pies, no labels");
    }

    #[test]
    fn outlines_paint_the_selected_state_last_and_darker() {
        let v: serde_json::Value = serde_json::from_str(&outlines_geojson(Some(6))).unwrap();
        let f = v["features"].as_array().unwrap();
        assert_eq!(f.len(), 51);
        let last = &f[50]["properties"];
        assert_eq!(last["fips"], 6);
        assert_eq!(last["line-color"], SELECTED_COLOR);
        assert_eq!(f[0]["properties"]["line-color"], OUTLINE_COLOR);
        let none: serde_json::Value = serde_json::from_str(&outlines_geojson(None)).unwrap();
        assert!(none["features"].as_array().unwrap().iter().all(|f| f["properties"]["line-color"] == OUTLINE_COLOR));
        assert!(OUTLINES.len() < 400_000, "the committed outlines stay small");
    }

    #[test]
    fn a_state_fit_frames_its_box() {
        let ca = by_fips(6).unwrap();
        let (lon, lat, z) = fit(ca, 1280.0, 800.0);
        assert!((-125.0..-114.0).contains(&lon) && (32.0..42.0).contains(&lat), "{lon},{lat}");
        assert!((4.5..6.5).contains(&z), "{z}");
        let dc = by_fips(11).unwrap();
        assert_eq!(fit(dc, 1280.0, 800.0).2, FIT_MAX_ZOOM);
        let ak = by_fips(2).unwrap();
        let (lon, _, z) = fit(ak, 1280.0, 800.0);
        assert!(lon < -140.0 && z >= walker::MIN_ZOOM, "{lon} z{z}");
    }
}
